    {'name': 'RI_Weapon_GoldSnakeSpear', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/SecondRate/RI_Weapon_GoldSnakeSpear.png', 'ing': [('RI_Resource_SpiritualCrystal', 10), ('RI_Resource_DeviceCoreComponent', 1), ('Gold', 5), ('STUFF_Metallic', 100)], 'work': 15000, 'mass': 2.0, 'sharp': 0.0, 'power': 45.0, 'verb': None, 'off': {}, 'cn': '鎏金蛇矛【二品】', 'cndesc': '一把鎏金风格的蛇矛，外形华丽，经过炼器之法的处理，具有强大的杀伤力。'},
    {'name': 'RI_Weapon_JadeBambooSword', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponRanged/RI_Weapon_JadeBambooSword.png', 'ing': [('RI_Resource_JadeBloodBamboo', 40), ('RI_Resource_SpiritualCrystal', 3)], 'work': 5000, 'mass': 1.0, 'sharp': 0.0, 'power': 18.0, 'verb': (15.0, 3, 17, None), 'off': {}, 'cn': '苍竹剑【三品】', 'cndesc': '【特殊效果】发射物护甲穿透+25%。'},
    {'name': 'RI_Weapon_JadeBambooBlade', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponRanged/RI_Weapon_JadeBambooBlade.png', 'ing': [('RI_Resource_JadeBloodBamboo', 40), ('RI_Resource_SpiritualCrystal', 3)], 'work': 5000, 'mass': 1.2, 'sharp': 0.0, 'power': 18.0, 'verb': (15.0, 2, 19, None), 'off': {}, 'cn': '苍血刀【三品】', 'cndesc': '【特殊效果】发射物护甲穿透+25%。'},
    {'name': 'RI_Weapon_JadeBambooFlyKnife', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponRanged/RI_Weapon_JadeBambooFlyKnife.png', 'ing': [('RI_Resource_JadeBloodBamboo', 30), ('RI_Resource_SpiritualCrystal', 5)], 'work': 5000, 'mass': 0.5, 'sharp': 0.0, 'power': 15.0, 'verb': (15.0, 5, 12, None), 'off': {}, 'cn': '苍竹飞刀【三品】', 'cndesc': '【特殊效果】发射物护甲穿透+25%。'},
    {'name': 'RI_Weapon_JadeBambooSpear', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponRanged/RI_Weapon_JadeBambooSpear.png', 'ing': [('RI_Resource_JadeBloodBamboo', 45), ('RI_Resource_SpiritualCrystal', 3)], 'work': 7000, 'mass': 1.5, 'sharp': 0.0, 'power': 22.0, 'verb': (9.0, 1, 25, None), 'off': {}, 'cn': '苍竹枪【三品】', 'cndesc': '【特殊效果】发射物护甲穿透+25%。'},
    {'name': 'RI_Weapon_JumenAxe', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/RI_Weapon_JumenAxe.png', 'ing': [('RI_Resource_DeviceCoreComponent', 2), ('Steel', 200), ('Silver', 30)], 'work': 21000, 'mass': 15.0, 'sharp': 0.0, 'power': 35.0, 'verb': None, 'off': {}, 'cn': '巨门斧【二品】', 'cndesc': '一柄源自古代的神兵之斧，以大量的金属锻造而成，其上刻满了纹路。手持斧子的时候激发灵气，斧子会发出一阵阵低沉的鸣叫，影响范围内的人。'},
    {'name': 'RI_Weapon_DESword', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponRanged/RI_Weapon_DESword.png', 'ing': [('RI_Resource_DeviceCoreComponent', 2), ('Steel', 100), ('Jade', 20), ('Wastepack', 5)], 'work': 25000, 'mass': 3.0, 'sharp': 0.0, 'power': 27.0, 'verb': None, 'off': {}, 'cn': '毒心梭【二品】', 'cndesc': '一柄可以自由操控飞行的飞梭，以猛毒萃成，是一种可怕的暗杀武器。'},
    {'name': 'RI_Weapon_CyanogenJadeHammer', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/RI_Weapon_CyanogenJadeHammer.png', 'ing': [('RI_Resource_DeviceCoreComponent', 2), ('Jade', 100), ('WoodLog', 100), ('Steel', 100)], 'work': 25000, 'mass': 20.0, 'sharp': 0.0, 'power': 30.0, 'verb': None, 'off': {}, 'cn': '青玉锤【二品】', 'cndesc': '一柄看上去十分脆弱的巨锤，但实际上非常坚固，宛如一体。'},
    {'name': 'RI_Weapons_WindDemonBlade', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/RI_Weapon_WindDemonBlade.png', 'ing': [('RI_Resource_DeviceCoreComponent', 2), ('Steel', 200), ('Uranium', 50)], 'work': 22000, 'mass': 9.0, 'sharp': 0.0, 'power': 25.0, 'verb': None, 'off': {}, 'cn': '风魔刀【二品】', 'cndesc': '一柄可以释放狂风的大刀。虽然是金属打造，但其上的纹路仿佛血管和肌腱一般，在挥动时隐隐跳动着。'},
    {'name': 'RI_Weapon_ThunderLordLance', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/RI_Weapon_ThunderLordLance.png', 'ing': [('RI_Resource_DeviceCoreComponent', 2), ('Steel', 200), ('Silver', 20), ('Gold', 20)], 'work': 26000, 'mass': 13.0, 'sharp': 0.0, 'power': 37.0, 'verb': None, 'off': {}, 'cn': '雷王枪【二品】', 'cndesc': '一柄威力强大的长枪，周身释放出道道闪电。这把武器据说曾是可以比肩一品的强大兵器，但之后由于过于不稳定，被经过改造，减小了威力，也更好控制了。'},
    {'name': 'RI_Weapon_RatWhiskerSword', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/RI_Weapon_RatWhiskerSword.png', 'ing': [('RI_Resource_DeviceCoreComponent', 2), ('Steel', 250), ('Jade', 30)], 'work': 28000, 'mass': 4.0, 'sharp': 0.0, 'power': 35.0, 'verb': None, 'off': {}, 'cn': '鼠须剑【二品】', 'cndesc': '一柄细剑，因为形似老鼠的胡须一般小巧，所以被称为鼠须剑。'},
    {'name': 'RI_Weapon_DragonCannon', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponRanged/RI_Weapon_DragonCannon.png', 'ing': [('RI_Resource_DeviceCoreComponent', 1), ('WoodLog', 100), ('Steel', 150), ('Plasteel', 50)], 'work': 25000, 'mass': 16.0, 'sharp': 0.0, 'power': 9.0, 'verb': (35.0, 3, 20, None), 'off': {}, 'cn': '龙头炮【二品】', 'cndesc': '一把龙头形状的火铳，加装了激光发射系统。这把武器说是手铳，但是口径更接近于炮弹，射出高温的弹丸，杀伤力恐怖。同时这把武器还能调整枪口，射出经过法阵加持的高温激光。'},
    {'name': 'RI_Weapon_FlyGrenade', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponRanged/RI_Weapon_FlyGrenade.png', 'ing': [('RI_Resource_DeviceCoreComponent', 2), ('Steel', 150), ('Plasteel', 50)], 'work': 27000, 'mass': 15.0, 'sharp': 0.0, 'power': 9.0, 'verb': (18.0, 1, 10, '2.1'), 'off': {}, 'cn': '飞蝇雷【二品】', 'cndesc': '据说这种武器的设计灵感来源于嗡嗡的苍蝇，可以通过特制的炮管连射小型的手雷，疯狂骚扰敌人，如同苍蝇一般烦人。'},
    {'name': 'RI_Weapon_GhostFireCrossbow', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponRanged/RI_Weapon_GhostFireCrossbow.png', 'ing': [('RI_Resource_DeviceCoreComponent', 2), ('Steel', 200), ('Jade', 30)], 'work': 25000, 'mass': 14.0, 'sharp': 0.0, 'power': 9.0, 'verb': (29.9, 5, 17, None), 'off': {}, 'cn': '鬼火连弩【二品】', 'cndesc': '一把经过法阵附上了鬼火烧灼的连弩，内部隐藏了机械结构，可以以极强的威力射出短弩箭。消耗灵石可以激发鬼火，射出带有爆炸燃烧效果的弩箭。'},
    {'name': 'RI_Weapon_IronThrowingBall', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponRanged/RI_Weapon_IronThrowingBall.png', 'ing': [('RI_Resource_DeviceCoreComponent', 2), ('Steel', 250), ('Cloth', 100)], 'work': 24000, 'mass': 9.0, 'sharp': 0.0, 'power': 9.0, 'verb': (15.0, 1, 30, None), 'off': {}, 'cn': '铁乌鸡【二品】', 'cndesc': '一种暗器，每颗铁乌鸡都有拳头大小，可以根据主人的心意自动悬浮或攻击，如臂使指，但是操控太多铁乌鸡会耗费心神。据说有人可以一次性控制九颗铁乌鸡，其连发的威力足以顷刻间清空周身敌人。'},
    {'name': 'RI_Weapon_MartialArtistBandage', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/RI_Weapon_MartialArtistBandage.png', 'ing': [('STUFF_Fabric', 40)], 'work': 4200, 'mass': 2.0, 'sharp': 0.0, 'power': 1.0, 'verb': None, 'off': {}, 'cn': '武术绑带', 'cndesc': '一种简单的拳套。只是简单地用织物包裹在拳头上，防止手指骨折，这是古人也知道的常识。'},
    {'name': 'RI_Weapon_BoxingGloves', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/RI_Weapon_BoxingGloves.png', 'ing': [('STUFF_Fabric', 40)], 'work': 4200, 'mass': 2.0, 'sharp': 0.0, 'power': 2.0, 'verb': None, 'off': {}, 'cn': '拳套', 'cndesc': '皮质的拳套，在关节等部位额外加装了厚皮片，增加耐用性。这种拳套更加沉重，但是打出的拳头具有炮弹一样的穿透力，低估拳击的敌人往往会吃亏。'},
    {'name': 'RI_Weapon_BasicSword', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/ThirdRate/RI_Weapon_BasicSword.png', 'ing': [('RI_Resource_SpiritualCrystal', 5), ('STUFF_Metallic', 70)], 'work': 10000, 'mass': 1.2, 'sharp': 0.0, 'power': 21.0, 'verb': None, 'off': {}, 'cn': '玄剑【三品】', 'cndesc': '一把具有微弱灵气的单手剑。外形古朴，但是仔细观察能看到浅浅的花纹图案，具有强大的切割能力。'},
    {'name': 'RI_Weapon_BasicAxe', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/ThirdRate/RI_Weapon_BasicAxe.png', 'ing': [('RI_Resource_SpiritualCrystal', 5), ('STUFF_Metallic', 100)], 'work': 11000, 'mass': 1.8, 'sharp': 0.0, 'power': 18.0, 'verb': None, 'off': {}, 'cn': '劈山斧【三品】', 'cndesc': '一柄具有微弱灵气的斧头。具有非常强大的切割能力，甚至可以用来劈开石头。'},
    {'name': 'RI_Weapon_BasicSaber', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/ThirdRate/RI_Weapon_BasicSaber.png', 'ing': [('RI_Resource_SpiritualCrystal', 5), ('STUFF_Metallic', 100)], 'work': 11000, 'mass': 1.5, 'sharp': 0.0, 'power': 25.0, 'verb': None, 'off': {}, 'cn': '追风刀【三品】', 'cndesc': '一把具有微弱灵气的双手刀。是一种重心靠前的武器，比较沉重，只有那些勇猛的斗士才会选择这样的武器，但一旦熟练，将会在战斗中形成恐怖的杀伤力。'},
    {'name': 'RI_Weapon_BasicHammer', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/ThirdRate/RI_Weapon_BasicHammer.png', 'ing': [('RI_Resource_SpiritualCrystal', 5), ('STUFF_Metallic', 120)], 'work': 10000, 'mass': 2.5, 'sharp': 0.0, 'power': 19.0, 'verb': None, 'off': {}, 'cn': '龙岩锤【三品】', 'cndesc': '一柄具有微弱灵气的单手锤。用石头捶打切割而成，厚重的锤头可以砸碎盔甲，如果砸不碎，起码也可以眩晕对手一段时间。'},
    {'name': 'RI_Weapon_BasicSpear', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/ThirdRate/RI_Weapon_BasicSpear.png', 'ing': [('RI_Resource_SpiritualCrystal', 5), ('STUFF_Metallic', 100)], 'work': 10000, 'mass': 2.0, 'sharp': 0.0, 'power': 23.0, 'verb': None, 'off': {}, 'cn': '穿心矛【三品】', 'cndesc': '一柄具有微弱灵气的长矛。在战士手中，能让枪如臂使指般出击。曾有一名士兵，一枪洞穿了敌人的心脏，但长矛卡住无法拔出，导致被其他敌人杀死。后人改进了这种长矛的形制，加上了护栏，以至于不'},
    {'name': 'RI_Weapon_ThrumboHornPushDagger', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponMelee/ThirdRate/RI_Weapon_ThrumboHornPushDagger.png', 'ing': [('RI_Resource_SpiritualCrystal', 5), ('STUFF_Metallic', 70)], 'work': 10000, 'mass': 1.2, 'sharp': 0.0, 'power': 15.0, 'verb': None, 'off': {}, 'cn': '拳刺【三品】', 'cndesc': '一对具有微弱灵气的拳刺，外形小巧别致，但攻击速度很快，蕴含了强大的杀伤力。'},
    {'name': 'RI_Weapon_Harquebus', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponRanged/ThirdRate/RI_Weapon_Harquebus.png', 'ing': [('Steel', 60), ('ComponentIndustrial', 1), ('RI_Resource_SpiritualCrystal', 5)], 'work': 8000, 'mass': 3.5, 'sharp': 0.0, 'power': 12.0, 'verb': (25.0, 3, 22, None), 'off': {}, 'cn': '连珠炮【三品】', 'cndesc': '一杆样貌古朴的火绳枪，但是使用了相当优秀的材料，可以连续射出三发灵弹。'},
    {'name': 'RI_Weapon_LongRangeMusket', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponRanged/ThirdRate/RI_Weapon_LongRangeMusket.png', 'ing': [('Steel', 80), ('ComponentIndustrial', 1), ('RI_Resource_SpiritualCrystal', 5)], 'work': 12000, 'mass': 8.0, 'sharp': 0.0, 'power': 12.0, 'verb': (40.0, 1, 35, None), 'off': {}, 'cn': '鹰眼火枪【三品】', 'cndesc': '一种基于早期火枪改造而来的远射火枪，远距离命中率较高，射出的灵弹威力也更高。'},
    {'name': 'RI_Weapon_BasicBow', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponRanged/ThirdRate/RI_Weapon_BasicBow.png', 'ing': [('WoodLog', 70), ('RI_Resource_SpiritualCrystal', 5)], 'work': 2400, 'mass': 0.3, 'sharp': 0.0, 'power': 9.0, 'verb': (28.0, 1, 15, None), 'off': {}, 'cn': '飞蝗弓【三品】', 'cndesc': '一支用灵气特殊加强处理的复合弓，非常轻便柔韧，如同蝗虫的腿一般，故得名飞蝗弓。'},
    {'name': 'RI_Weapon_ThrowingKnife', 'tex': '3308873789/Textures/Things/Item/Equipment/WeaponRanged/ThirdRate/RI_Weapon_ThrowingKnife.png', 'ing': [('Steel', 70)], 'work': 7000, 'mass': 4.0, 'sharp': 0.0, 'power': 15.0, 'verb': (18.9, 1, 25, None), 'off': {}, 'cn': '脱手镖【三品】', 'cndesc': '一种飞镖暗器，在其中镶嵌了灵石以产生更大的伤害。这种暗器被正道人士所不齿，但由于其实用性，所以许多行者都会带一两个暗器防身。'},
    {'name': 'TW_MeleeWeapon_Flail', 'tex': '3420195156/Textures/Things/Item/Equipment/WeaponMelee/TW_MeleeWeapon_Flail.png', 'ing': [('STUFF_Metallic', 80)], 'work': 7200, 'mass': 1.5, 'sharp': 0.0, 'power': 25.0, 'verb': None, 'off': {'PlantWorkSpeed': 0.05, 'PlantHarvestYield': 0.05, 'MeleeHitChance': -2.0}, 'cn': '梢子棍', 'cndesc': '农民用来打谷子的农具，一根长棍通过链条连接短棍，挥动长棍带动短棍，敲打更加省力。'},
    {'name': 'TW_MeleeWeapon_TStick', 'tex': '3420195156/Textures/Things/Item/Equipment/WeaponMelee/TW_MeleeWeapon_TStick.png', 'ing': [('STUFF_Metallic', 40)], 'work': 6000, 'mass': 0.6, 'sharp': 0.0, 'power': 10.0, 'verb': None, 'off': {'MeleeDodgeChance': 10.0}, 'cn': '拐棍', 'cndesc': '据说是基于农具改进的拐棍，外形普通，却攻防一体，既可作护手，又可作短棍使用。'},
    {'name': 'TW_MeleeWeapon_SwordBreaker', 'tex': '3420195156/Textures/Things/Item/Equipment/WeaponMelee/TW_MeleeWeapon_SwordBreaker.png', 'ing': [('STUFF_Metallic', 70)], 'work': 12000, 'mass': 1.4, 'sharp': 0.0, 'power': 15.0, 'verb': None, 'off': {}, 'cn': '锏', 'cndesc': '锏的主体为一根四面长锥，边缘甚至能击碎袭来的刀剑，是攻防兼备的钝器。'},
    {'name': 'TW_MeleeWeapon_HandFork', 'tex': '3420195156/Textures/Things/Item/Equipment/WeaponMelee/TW_MeleeWeapon_HandFork.png', 'ing': [('STUFF_Metallic', 50)], 'work': 6000, 'mass': 1.25, 'sharp': 0.0, 'power': 13.0, 'verb': None, 'off': {'MeleeDodgeChance': 5.0}, 'cn': '短尺', 'cndesc': '外形像叉子的短兵器，护手可以很好地格挡兵器，灵活又不太致命，因此常被捕快使用。'},
    {'name': 'TW_MeleeWeapon_LengthStick', 'tex': '3420195156/Textures/Things/Item/Equipment/WeaponMelee/TW_MeleeWeapon_LengthStick.png', 'ing': [('STUFF_Metallic', 50)], 'work': 1500, 'mass': 1.5, 'sharp': 0.0, 'power': 12.0, 'verb': None, 'off': {'MoveSpeed': 0.5}, 'cn': '齐眉棍', 'cndesc': '平平无奇的长棍，但可不要被其外形欺骗。擅长用棍之人可凭借棍法千变万化，对无甲目标造成破坏性伤害。'},
    {'name': 'TW_MeleeWeapon_ShortDao', 'tex': '3420195156/Textures/Things/Item/Equipment/WeaponMelee/TW_MeleeWeapon_ShortDao.png', 'ing': [('STUFF_Metallic', 40)], 'work': 6000, 'mass': 0.7, 'sharp': 0.0, 'power': 15.0, 'verb': None, 'off': {}, 'cn': '横刀', 'cndesc': '朴实的短横刀，比匕首略长。'},
    {'name': 'TW_MeleeWeapon_WoodChopper', 'tex': '3420195156/Textures/Things/Item/Equipment/WeaponMelee/TW_MeleeWeapon_WoodChopper.png', 'ing': [('STUFF_Metallic', 40)], 'work': 5000, 'mass': 1.0, 'sharp': 0.0, 'power': 15.0, 'verb': None, 'off': {'PlantWorkSpeed': 0.05, 'ButcheryFleshSpeed': 0.05}, 'cn': '柴刀', 'cndesc': '平头柴刀，除了自卫防身外，还能上山砍柴、下厨切菜，宽厚的刀背甚至可用作锤子。'},
    {'name': 'TW_MeleeWeapon_RingPommelDao', 'tex': '3420195156/Textures/Things/Item/Equipment/WeaponMelee/TW_MeleeWeapon_RingPommelDao.png', 'ing': [('STUFF_Metallic', 50)], 'work': 10000, 'mass': 2.0, 'sharp': 0.0, 'power': 16.0, 'verb': None, 'off': {}, 'cn': '环首刀', 'cndesc': '一种古朴的刀，刀柄上有一个环，可用布条绑住防止刀脱手。此刀没有护手，刀柄可直接埋入刀鞘中。'},
    {'name': 'TW_MeleeWeapon_TangDao', 'tex': '3420195156/Textures/Things/Item/Equipment/WeaponMelee/TW_MeleeWeapon_TangDao.png', 'ing': [('STUFF_Metallic', 100)], 'work': 18000, 'mass': 2.0, 'sharp': 0.0, 'power': 23.0, 'verb': None, 'off': {}, 'cn': '唐刀', 'cndesc': '性能优异的军用刀，制作工艺严谨。唐刀不仅耐用，其锋利度还足以破甲，堪称没有短板的刀。'},
    {'name': 'TW_MeleeWeapon_YanlingDao', 'tex': '3420195156/Textures/Things/Item/Equipment/WeaponMelee/TW_MeleeWeapon_YanlingDao.png', 'ing': [('STUFF_Metallic', 80)], 'work': 15000, 'mass': 1.2, 'sharp': 0.0, 'power': 16.0, 'verb': None, 'off': {}, 'cn': '雁翎刀', 'cndesc': '外形如羽毛般的弯刀，适合骑兵使用。雁翎刀不仅实战优秀，外形也十分华丽，深受官员喜爱。'},
